window.docContents[202].resolve({"/Elementary-Functions/___4___28-Definitions-and-Periodicity/#LMLF-___-DLMF-with-Lean--Elementary-Functions--___4___28-Definitions-and-Periodicity--___4___28-Definitions-and-Periodicity":{"contents":"The variables in this section are complex.  The first seven entries define\nthe hyperbolic functions from the exponential, quotient, and reciprocal\nconventions.  The next six identify hyperbolic functions with ordinary\ntrigonometric functions evaluated at an imaginary argument.  The reciprocal\ndefinitions use the usual totalized Lean division; away from zeros they are\nthe analytic functions represented by the DLMF notation.\n\n\n\n\n\n\n\n","context":"LMLF · DLMF with Lean\u0009Elementary Functions\u0009§4.28 Definitions and Periodicity","header":"§4.28 Definitions and Periodicity","id":"/Elementary-Functions/___4___28-Definitions-and-Periodicity/#LMLF-___-DLMF-with-Lean--Elementary-Functions--___4___28-Definitions-and-Periodicity--___4___28-Definitions-and-Periodicity"}});